    <title>Image Preview | Lumina Library</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f6f7fb;
        --surface: #ffffff;
        --surface-muted: #f1f5f9;
        --text: #111827;
        --muted: #5b6472;
        --border: #d8dee8;
        --primary: #2563eb;
        --primary-strong: #1d4ed8;
        --danger: #b91c1c;
        --danger-strong: #991b1b;
        --ring: #1d4ed8;
        --shadow: 0 24px 70px rgba(15, 23, 42, 0.16);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        background:
          radial-gradient(circle at top left, rgba(37, 99, 235, 0.14), transparent 32rem),
          linear-gradient(135deg, #f8fafc 0%, var(--bg) 45%, #eef2ff 100%);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-160%);
        border-radius: 999px;
        background: var(--text);
        color: #ffffff;
        padding: 0.65rem 1rem;
        font-weight: 700;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .site-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 1.25rem 0;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.7rem;
        color: var(--text);
        font-size: 1rem;
        font-weight: 800;
        text-decoration: none;
      }

      .brand-mark {
        display: grid;
        width: 2.35rem;
        height: 2.35rem;
        place-items: center;
        border-radius: 0.8rem;
        background: var(--text);
        color: #ffffff;
        font-weight: 900;
      }

      nav ul {
        display: flex;
        gap: 0.3rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      nav a {
        display: inline-flex;
        border-radius: 999px;
        color: var(--muted);
        padding: 0.6rem 0.9rem;
        font-weight: 700;
        text-decoration: none;
      }

      nav a[aria-current="page"] {
        background: var(--surface);
        color: var(--text);
        box-shadow: 0 1px 10px rgba(15, 23, 42, 0.08);
      }

      main {
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 2.5rem 0 4rem;
      }

      .hero {
        display: grid;
        gap: 1rem;
        margin-bottom: 2rem;
      }

      .eyebrow {
        color: var(--primary);
        font-size: 0.78rem;
        font-weight: 900;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      h1,
      h2,
      p {
        margin-top: 0;
      }

      h1 {
        max-width: 14ch;
        margin-bottom: 0;
        font-size: clamp(2.5rem, 7vw, 5.5rem);
        letter-spacing: -0.07em;
        line-height: 0.92;
      }

      .lede {
        max-width: 62ch;
        margin-bottom: 0;
        color: var(--muted);
        font-size: clamp(1rem, 1.8vw, 1.18rem);
      }

      .preview-card {
        display: grid;
        grid-template-columns: minmax(0, 1.35fr) minmax(18rem, 0.65fr);
        overflow: hidden;
        border: 1px solid rgba(216, 222, 232, 0.85);
        border-radius: 2rem;
        background: rgba(255, 255, 255, 0.82);
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      .image-panel {
        display: grid;
        gap: 1rem;
        padding: clamp(1rem, 3vw, 1.5rem);
      }

      figure {
        margin: 0;
      }

      .preview-image {
        display: block;
        width: 100%;
        aspect-ratio: 16 / 11;
        border-radius: 1.35rem;
        object-fit: cover;
        background: var(--surface-muted);
      }

      figcaption {
        margin-top: 0.85rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .details-panel {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        gap: 1.5rem;
        border-left: 1px solid var(--border);
        background: rgba(248, 250, 252, 0.84);
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .meta-list {
        display: grid;
        gap: 0.85rem;
        margin: 1.4rem 0 0;
      }

      .meta-row {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        border-bottom: 1px solid var(--border);
        padding-bottom: 0.85rem;
      }

      .meta-row dt {
        color: var(--muted);
        font-weight: 700;
      }

      .meta-row dd {
        margin: 0;
        font-weight: 800;
        text-align: right;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      .button {
        display: inline-flex;
        min-height: 2.75rem;
        align-items: center;
        justify-content: center;
        gap: 0.45rem;
        border: 1px solid transparent;
        border-radius: 999px;
        padding: 0.75rem 1rem;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      .button-secondary {
        border-color: var(--border);
        background: var(--surface);
        color: var(--text);
      }

      .button-primary {
        background: var(--primary);
        color: #ffffff;
      }

      .button-primary:hover {
        background: var(--primary-strong);
      }

      .button-danger {
        background: var(--danger);
        color: #ffffff;
      }

      .button-danger:hover {
        background: var(--danger-strong);
      }

      .button-subtle {
        border-color: var(--border);
        background: #ffffff;
        color: var(--text);
      }

      .status {
        margin-top: 1rem;
        border: 1px solid #bfdbfe;
        border-radius: 1rem;
        background: #eff6ff;
        color: #1e3a8a;
        padding: 1rem;
        font-weight: 700;
      }

      .status:empty {
        display: none;
      }

      dialog {
        width: min(92vw, 32rem);
        border: 0;
        border-radius: 1.5rem;
        background: var(--surface);
        color: var(--text);
        padding: 0;
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(15, 23, 42, 0.55);
        backdrop-filter: blur(5px);
      }

      .dialog-inner {
        display: grid;
        gap: 1rem;
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        place-items: center;
        border-radius: 1rem;
        background: #fee2e2;
        color: var(--danger);
      }

      .dialog-icon svg {
        width: 1.4rem;
        height: 1.4rem;
      }

      dialog h2 {
        margin-bottom: 0.35rem;
        font-size: clamp(1.45rem, 5vw, 2rem);
        letter-spacing: -0.04em;
        line-height: 1.05;
      }

      .dialog-copy {
        margin-bottom: 0;
        color: var(--muted);
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap-reverse;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 0.5rem;
      }

      :focus-visible {
        outline: 3px solid var(--ring);
        outline-offset: 3px;
      }

      @media (max-width: 760px) {
        .site-header,
        nav ul,
        .preview-card,
        .meta-row {
          display: grid;
        }

        .site-header {
          align-items: start;
        }

        nav ul {
          grid-template-columns: repeat(3, max-content);
        }

        .preview-card {
          grid-template-columns: 1fr;
          border-radius: 1.35rem;
        }

        .details-panel {
          border-top: 1px solid var(--border);
          border-left: 0;
        }

        .meta-row dd {
          text-align: left;
        }
      }

      @media (max-width: 420px) {
        body {
          background: var(--bg);
        }

        .site-header,
        main {
          width: min(100% - 1rem, 1120px);
        }

        main {
          padding-top: 1rem;
        }

        nav ul,
        .actions,
        .dialog-actions {
          grid-template-columns: 1fr;
        }

        nav a,
        .button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-muted: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: ButtonBorder;
          --primary: Highlight;
          --primary-strong: Highlight;
          --danger: ButtonText;
          --danger-strong: ButtonText;
          --ring: Highlight;
          --shadow: none;
        }

        .preview-card,
        dialog,
        .status,
        nav a[aria-current="page"] {
          border: 1px solid ButtonBorder;
          box-shadow: none;
        }

        .button {
          border-color: ButtonBorder;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>

    <header class="site-header">
      <a class="brand" href="#" aria-label="Lumina Library home">
        <span class="brand-mark" aria-hidden="true">L</span>
        <span>Lumina Library</span>
      </a>
      <nav aria-label="Primary">
        <ul>
          <li><a href="#">Gallery</a></li>
          <li><a href="#" aria-current="page">Preview</a></li>
          <li><a href="#">Shared</a></li>
        </ul>
      </nav>
    </header>

    <main id="maincontent" tabindex="-1">
      <section class="hero" aria-labelledby="page-title">
        <p class="eyebrow">Image preview</p>
        <h1 id="page-title">Coastal Dawn</h1>
        <p class="lede">
          Review the selected image before keeping it in your library, sharing it with a collection,
          or removing it from your saved assets.
        </p>
      </section>

      <article class="preview-card" id="image-card" aria-labelledby="image-title">
        <div class="image-panel">
          <figure>
            <img
              class="preview-image"
              src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&amp;fit=crop&amp;w=1400&amp;q=80"
              alt="Sunlight breaking over a quiet coastal landscape with hills and water"
            >
            <figcaption>Uploaded April 28, 2026 by Maya Chen.</figcaption>
          </figure>
        </div>

        <div class="details-panel">
          <div>
            <h2 id="image-title">Library details</h2>
            <p class="dialog-copy">
              This high-resolution image is currently available in your personal library.
            </p>
            <dl class="meta-list">
              <div class="meta-row">
                <dt>Format</dt>
                <dd>JPEG</dd>
              </div>
              <div class="meta-row">
                <dt>Dimensions</dt>
                <dd>4200 × 2880</dd>
              </div>
              <div class="meta-row">
                <dt>Collection</dt>
                <dd>Travel concepts</dd>
              </div>
            </dl>
          </div>

          <div class="actions" aria-label="Image actions">
            <button class="button button-secondary" type="button">Download</button>
            <button
              class="button button-danger trigger"
              type="button"
              aria-haspopup="dialog"
              aria-controls="delete-dialog"
            >
              Delete image
            </button>
          </div>
        </div>
      </article>

      <p class="status" id="status-message" role="status" tabindex="-1"></p>
    </main>

    <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
      <form method="dialog" class="dialog-inner">
        <div class="dialog-icon" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none" focusable="false">
            <path
              d="M10 11v6M14 11v6M5 7h14M9 7V5h6v2m-8 0 1 13h8l1-13"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </div>

        <div>
          <h2 id="dialog-title">Delete this image?</h2>
          <p class="dialog-copy" id="dialog-description">
            Coastal Dawn will be removed from your library. This action cannot be undone.
          </p>
        </div>

        <div class="dialog-actions">
          <button class="button button-subtle" value="cancel" type="submit" autofocus>Cancel</button>
          <button class="button button-danger" value="delete" type="submit">Delete image</button>
        </div>
      </form>
    </dialog>

    <script>
      const deleteDialog = document.getElementById("delete-dialog");
      const deleteTrigger = document.querySelector(".trigger");
      const imageCard = document.getElementById("image-card");
      const statusMessage = document.getElementById("status-message");

      deleteTrigger.addEventListener("click", () => {
        deleteDialog.showModal();
      });

      deleteDialog.addEventListener("close", () => {
        if (deleteDialog.returnValue !== "delete") {
          return;
        }

        imageCard.hidden = true;
        statusMessage.textContent = "Coastal Dawn has been deleted from your library.";
        statusMessage.focus();
      });
    </script>
  </body>
</html>
