         margin-bottom: 0;
         font-size: clamp(2.5rem, 7vw, 5.5rem);
         letter-spacing: -0.07em;
         line-height: 0.92;
       }

       .lede {
         max-width: 62ch;
         margin-bottom: 0;
         color: var(--muted);
         font-size: clamp(1rem, 1.8vw, 1.18rem);
       }

       .preview-card {
         display: grid;
         grid-template-columns: minmax(0, 1.35fr) minmax(18rem, 0.65fr);
         overflow: hidden;
         border: 1px solid rgba(216, 222, 232, 0.85);
         border-radius: 2rem;
         background: rgba(255, 255, 255, 0.82);
         box-shadow: var(--shadow);
         backdrop-filter: blur(18px);
       }

       .image-panel {
         display: grid;
         gap: 1rem;
         padding: clamp(1rem, 3vw, 1.5rem);
       }

       figure {
         margin: 0;
       }

       .preview-image {
         display: block;
         width: 100%;
         aspect-ratio: 16 / 11;
         border-radius: 1.35rem;
         object-fit: cover;
         background: var(--surface-muted);
       }

       figcaption {
         margin-top: 0.85rem;
         color: var(--muted);
         font-size: 0.95rem;
       }

       .details-panel {
         display: flex;
         flex-direction: column;
         justify-content: space-between;
         gap: 1.5rem;
         border-left: 1px solid var(--border);
         background: rgba(248, 250, 252, 0.84);
         padding: clamp(1.25rem, 4vw, 2rem);
       }

       .meta-list {
         display: grid;
         gap: 0.85rem;
         margin: 1.4rem 0 0;
       }

       .meta-row {
         display: flex;
         justify-content: space-between;
         gap: 1rem;
         border-bottom: 1px solid var(--border);
         padding-bottom: 0.85rem;
       }

       .meta-row dt {
         color: var(--muted);
         font-weight: 700;
       }

       .meta-row dd {
         margin: 0;
         font-weight: 800;
         text-align: right;
       }

       .actions {
         display: flex;
         flex-wrap: wrap;
         gap: 0.75rem;
       }

       .button {
         display: inline-flex;
         min-height: 2.75rem;
         align-items: center;
         justify-content: center;
         gap: 0.45rem;
         border: 1px solid transparent;
         border-radius: 999px;
         padding: 0.75rem 1rem;
         font: inherit;
         font-weight: 800;
         cursor: pointer;
       }

       .button-secondary {
         border-color: var(--border);
         background: var(--surface);
         color: var(--text);
       }

       .button-primary {
         background: var(--primary);
         color: #ffffff;
       }

       .button-primary:hover {
         background: var(--primary-strong);
       }

       .button-danger {
         background: var(--danger);
         color: #ffffff;
       }

       .button-danger:hover {
         background: var(--danger-strong);
       }

       .button-subtle {
         border-color: var(--border);
         background: #ffffff;
         color: var(--text);
       }

       .status {
         margin-top: 1rem;
         border: 1px solid #bfdbfe;
         border-radius: 1rem;
         background: #eff6ff;
         color: #1e3a8a;
         padding: 1rem;
         font-weight: 700;
       }

       .status:empty {
         display: none;
       }

       dialog {
         width: min(92vw, 32rem);
         border: 0;
         border-radius: 1.5rem;
         background: var(--surface);
         color: var(--text);
         padding: 0;
         box-shadow: var(--shadow);
       }

       dialog::backdrop {
         background: rgba(15, 23, 42, 0.55);
         backdrop-filter: blur(5px);
       }

       .dialog-inner {
         display: grid;
         gap: 1rem;
         padding: clamp(1.25rem, 5vw, 2rem);
       }

       .dialog-icon {
         display: grid;
         width: 3rem;
         height: 3rem;
         place-items: center;
         border-radius: 1rem;
         background: #fee2e2;
         color: var(--danger);
       }

       .dialog-icon svg {
         width: 1.4rem;
         height: 1.4rem;
       }

       dialog h2 {
         margin-bottom: 0.35rem;
         font-size: clamp(1.45rem, 5vw, 2rem);
         letter-spacing: -0.04em;
         line-height: 1.05;
       }

       .dialog-copy {
         margin-bottom: 0;
         color: var(--muted);
       }

       .dialog-actions {
         display: flex;
         flex-wrap: wrap-reverse;
         justify-content: flex-end;
         gap: 0.75rem;
         margin-top: 0.5rem;
       }

       :focus-visible {
         outline: 3px solid var(--ring);
         outline-offset: 3px;
       }

       @media (max-width: 760px) {
         .site-header,
         nav ul,
         .preview-card,
         .meta-row {
           display: grid;
         }

         .site-header {
           align-items: start;
         }

         nav ul {
           grid-template-columns: repeat(3, max-content);
         }

         .preview-card {
           grid-template-columns: 1fr;
           border-radius: 1.35rem;
         }

         .details-panel {
           border-top: 1px solid var(--border);
           border-left: 0;
         }

         .meta-row dd {
           text-align: left;
         }
       }

       @media (max-width: 420px) {
         body {
           background: var(--bg);
         }

         .site-header,
         main {
           width: min(100% - 1rem, 1120px);
         }

         main {
           padding-top: 1rem;
         }

         nav ul,
         .actions,
         .dialog-actions {
           grid-template-columns: 1fr;
         }

         nav a,
         .button {
           width: 100%;
         }
       }

       @media (forced-colors: active) {
         :root {
           --bg: Canvas;
           --surface: Canvas;
           --surface-muted: Canvas;
           --text: CanvasText;
           --muted: CanvasText;
           --border: ButtonBorder;
           --primary: Highlight;
           --primary-strong: Highlight;
           --danger: ButtonText;
           --danger-strong: ButtonText;
           --ring: Highlight;
           --shadow: none;
         }

         .preview-card,
         dialog,
         .status,
         nav a[aria-current="page"] {
           border: 1px solid ButtonBorder;
           box-shadow: none;
         }

         .button {
           border-color: ButtonBorder;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>

     <header class="site-header">
       <a class="brand" href="#" aria-label="Lumina Library home">
         <span class="brand-mark" aria-hidden="true">L</span>
         <span>Lumina Library</span>
       </a>
       <nav aria-label="Primary">
         <ul>
           <li><a href="#">Gallery</a></li>
           <li><a href="#" aria-current="page">Preview</a></li>
           <li><a href="#">Shared</a></li>
         </ul>
       </nav>
     </header>

     <main id="maincontent" tabindex="-1">
       <section class="hero" aria-labelledby="page-title">
         <p class="eyebrow">Image preview</p>
         <h1 id="page-title">Coastal Dawn</h1>
         <p class="lede">
           Review the selected image before keeping it in your library, sharing it with a collection,
           or removing it from your saved assets.
         </p>
       </section>

       <article class="preview-card" id="image-card" aria-labelledby="image-title">
         <div class="image-panel">
           <figure>
             <img
               class="preview-image"
               src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1600 1100'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop offset='0' stop-color='%23dbeafe'/%3E%3Cstop offset='0.55' stop-color='%23f8fafc'/%3E%3Cstop offset='1' stop-color='%23bfdbfe'/%3E%3C/linearGradient%3E%3ClinearGradient id='sun' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23fef3c7'/%3E%3Cstop offset='1' stop-color='%23fb923c'/%3E%3C/linearGradient%3E%3ClinearGradient id='water' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%2393c5fd'/%3E%3Cstop offset='1' stop-color='%231e40af'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1600' height='1100' fill='url(%23sky)'/%3E%3Ccircle cx='1160' cy='300' r='150' fill='url(%23sun)' opacity='0.9'/%3E%3Cpath d='M0 570 C240 380 420 430 610 540 C800 650 930 510 1120 430 C1320 350 1460 390 1600 470 L1600 1100 L0 1100 Z' fill='%230f766e' opacity='0.88'/%3E%3Cpath d='M0 690 C260 560 430 640 650 690 C910 750 1110 610 1600 660 L1600 1100 L0 1100 Z' fill='%231d4ed8' opacity='0.82'/%3E%3Cpath d='M0 805 C240 760 420 790 610 830 C850 880 1080 805 1600 835 L1600 1100 L0 1100 Z' fill='url(%23water)'/%3E%3Cpath d='M120 895 C360 855 650 930 920 885 C1160 845 1350 875 1500 905' fill='none' stroke='%23e0f2fe' stroke-width='18' stroke-linecap='round' opacity='0.8'/%3E%3Cpath d='M230 970 C450 940 690 990 890 955 C1100 918 1275 945 1410 975' fill='none' stroke='%23eff6ff' stroke-width='14' stroke-linecap='round' opacity='0.7'/%3E%3C/svg%3E"
               alt="Sunlight breaking over a quiet coastal landscape with hills and water"
             >
             <figcaption>Uploaded April 28, 2026 by Maya Chen.</figcaption>
           </figure>
         </div>

         <div class="details-panel">
           <div>
             <h2 id="image-title">Library details</h2>
             <p class="dialog-copy">
               This high-resolution image is currently available in your personal library.
             </p>
             <dl class="meta-list">
               <div class="meta-row">
                 <dt>Format</dt>
                 <dd>JPEG</dd>
               </div>
               <div class="meta-row">
                 <dt>Dimensions</dt>
                 <dd>4200 × 2880</dd>
               </div>
               <div class="meta-row">
                 <dt>Collection</dt>
                 <dd>Travel concepts</dd>
               </div>
             </dl>
           </div>

           <div class="actions" aria-label="Image actions">
             <button class="button button-secondary" type="button">Download</button>
             <button
               class="button button-danger trigger"
               type="button"
               aria-haspopup="dialog"
               aria-controls="delete-dialog"
             >
               Delete image
             </button>
           </div>
         </div>
       </article>

       <p class="status" id="status-message" role="status" tabindex="-1"></p>
     </main>

     <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
       <form method="dialog" class="dialog-inner">
         <div class="dialog-icon" aria-hidden="true">
           <svg viewBox="0 0 24 24" fill="none" focusable="false">
             <path
               d="M10 11v6M14 11v6M5 7h14M9 7V5h6v2m-8 0 1 13h8l1-13"
               stroke="currentColor"
               stroke-width="2"
               stroke-linecap="round"
               stroke-linejoin="round"
             />
           </svg>
         </div>

         <div>
           <h2 id="dialog-title">Delete this image?</h2>
           <p class="dialog-copy" id="dialog-description">
             Coastal Dawn will be removed from your library. This action cannot be undone.
           </p>
         </div>

         <div class="dialog-actions">
           <button class="button button-subtle" value="cancel" type="submit" autofocus>Cancel</button>
           <button class="button button-danger" value="delete" type="submit">Delete image</button>
         </div>
       </form>
     </dialog>

     <script>
       const deleteDialog = document.getElementById("delete-dialog");
       const deleteTrigger = document.querySelector(".trigger");
       const imageCard = document.getElementById("image-card");
       const statusMessage = document.getElementById("status-message");

       deleteTrigger.addEventListener("click", () => {
         deleteDialog.showModal();
       });

       deleteDialog.addEventListener("close", () => {
         if (deleteDialog.returnValue !== "delete") {
           return;
         }

         imageCard.hidden = true;
         statusMessage.textContent = "Coastal Dawn has been deleted from your library.";
         statusMessage.focus();
       });
     </script>
   </body>
 </html>

')
